const report = $('Build Final Report1').item.json;
const resp = $json;
const isValidComparisonResult = resp && typeof resp.status === 'string' && ['PASS', 'WARN', 'FAIL'].includes(resp.status);
return [{
  json: {
    ...report,
    compare_result: isValidComparisonResult ? resp : null,
    compare_call_failed: !isValidComparisonResult,
    compare_call_error: !isValidComparisonResult
      ? (resp && (resp.error || resp.message || JSON.stringify(resp))) || 'Unknown error calling the table comparison service'
      : null
  }
}];

const cmp = $json.compare_result || {};
let cleanedCode = '';
try { cleanedCode = $('Base64 Encode').item.json.cleaned_code || ''; } catch (e) { cleanedCode = ''; }

return [{
  json: {
    ...$json,
    cleaned_code: cleanedCode,
    repair_cycle: $json.repair_cycles_used || 0,
    repair_reason: 'table_validation_gap',
    repair_detail: `Post-run table comparison returned ${cmp.status}. row_count_source=${cmp.row_count_source}, row_count_target=${cmp.row_count_target}, matched_rows=${cmp.matched_rows}, missing_rows=${cmp.missing_rows}, extra_rows=${cmp.extra_rows}, schema_match=${cmp.schema_match}. column_differences=${JSON.stringify(cmp.column_differences || [])}. sample_mismatches=${JSON.stringify(cmp.sample_mismatches || [])}. duplicate_rows=${JSON.stringify(cmp.duplicate_rows || {})}`,
    failure_pattern: 'Table Validation Mismatch'
  }
}];

const cmp = $json.compare_result;
const failed = $json.compare_call_failed === true;
const repairCycles = $json.repair_cycle != null ? $json.repair_cycle : ($json.repair_cycles_used || 0);

const report = { ...$json };
delete report.compare_result;
delete report.compare_call_failed;
delete report.compare_call_error;
delete report.cleaned_code;
delete report.repair_detail;
delete report.repair_reason;
delete report.failure_pattern;

let tableValidation;
if (failed) {
  tableValidation = {
    status: 'UNAVAILABLE',
    note: 'Could not reach the table comparison service: ' + ($json.compare_call_error || 'unknown connection error'),
    repair_cycles_used: repairCycles
  };
} else {
  tableValidation = {
    status: cmp ? cmp.status : 'UNKNOWN',
    row_count_source: cmp ? cmp.row_count_source : null,
    row_count_target: cmp ? cmp.row_count_target : null,
    matched_rows: cmp ? cmp.matched_rows : null,
    missing_rows: cmp ? cmp.missing_rows : null,
    extra_rows: cmp ? cmp.extra_rows : null,
    schema_match: cmp ? cmp.schema_match : null,
    column_differences: cmp ? cmp.column_differences : [],
    sample_mismatches: cmp ? cmp.sample_mismatches : [],
    repair_cycles_used: repairCycles
  };
}

return [{ json: { ...report, table_validation: tableValidation } }];

const item = $input.first();
const fileKey = Object.keys(item.binary || {})[0];
if (!fileKey) throw new Error('No uploaded file found on the form submission');
const binaryData = await this.helpers.getBinaryDataBuffer(0, fileKey);
const rawText = binaryData.toString('utf8');
const trimmed = rawText.trim();

let sourceFormat = 'unknown';
if (trimmed.startsWith('<')) {
  sourceFormat = 'alteryx_yxmd';
} else {
  let parsed = null;
  try { parsed = JSON.parse(trimmed); } catch (e) { parsed = null; }
  if (parsed) {
    const looksLikeAdfPipeline = !!(parsed.properties && Array.isArray(parsed.properties.activities));
    const looksLikeAdfDataFlow = !!(parsed.properties && (parsed.properties.type === 'MappingDataFlow' ||
      (parsed.properties.typeProperties && Array.isArray(parsed.properties.typeProperties.transformations))));
    const looksLikeAdfArmExport = Array.isArray(parsed.resources) &&
      parsed.resources.some(r => typeof r.type === 'string' && r.type.toLowerCase().includes('datafactory'));
    sourceFormat = (looksLikeAdfPipeline || looksLikeAdfDataFlow || looksLikeAdfArmExport) ? 'adf_json' : 'unknown_json';
  }
}
if (sourceFormat === 'unknown' || sourceFormat === 'unknown_json') {
  throw new Error('Unrecognized workflow file: expected an Alteryx .yxmd (XML) or an Azure Data Factory pipeline/dataflow export (.json)');
}

return [{
  json: {
    project_name: item.json['Project Name'],
    filename: item.binary[fileKey].fileName,
    source_format: sourceFormat,
    source_content: rawText,
    additional_info: item.json['Additional Information'] || item.json['additional information'] || '',
    repair_cycle: 0
  }
}];

// === Production Alteryx/ADF Parser (Canonical IR) ===
function parseAlteryxYXMD(xmlString, project_name, filename) {
  const workflow = {
    project_name: project_name,
    filename: filename,
    workflow_name: 'Unnamed Workflow',
    tool_count: 0,
    tools: [],
    connections: [],
    inputs: [],
    outputs: [],
    filters: [],
    formulas: [],
    sorts: [],
    joins: [],
    unions: [],
    aggregations: [],
    macros: [],
    execution_flow: [],
    execution_steps: [],
    dependency_graph: {},
    business_logic_candidates: []
  };

  function getAttrs(tagStr) {
    const attrs = {};
    if (!tagStr) return attrs;
    const attrRegex = /([\w:-]+)\s*=\s*"([^"]*)"/g;
    let m;
    while ((m = attrRegex.exec(tagStr)) !== null) attrs[m[1]] = m[2];
    return attrs;
  }
  function getTags(xml, tagName) {
    const results = [];
    if (!xml) return results;
    const regex = new RegExp('<' + tagName + '\\b([^>]*?)(?:/>|>([\\s\\S]*?)</' + tagName + '>)', 'gi');
    let m;
    while ((m = regex.exec(xml)) !== null) {
      results.push({ attrs: getAttrs(m[1]), inner: m[2] !== undefined ? m[2].trim() : '' });
    }
    return results;
  }
  function getTagText(xml, tagName) {
    if (!xml) return '';
    const m = xml.match(new RegExp('<' + tagName + '\\b[^>]*>([\\s\\S]*?)</' + tagName + '>', 'i'));
    return m ? m[1].trim() : '';
  }
  function decodeXmlEntities(str) {
    if (!str) return str;
    return str.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&');
  }
  function splitFilePath(raw) {
    if (!raw) return { path: '', extra: '' };
    const parts = raw.split('|||');
    return { path: parts[0] ? parts[0].trim() : '', extra: parts[1] ? parts[1].trim() : '' };
  }

  const nameMatch = xmlString.match(/<Name>([^<]+)<\/Name>/i);
  if (nameMatch) workflow.workflow_name = decodeXmlEntities(nameMatch[1].trim());

  function parseFormula(c) {
    const out = [];
    const fields = getTags(getTagText(c,'FormulaFields') || c, 'FormulaField');
    fields.forEach(f => out.push({ field: f.attrs.field || '', expression: decodeXmlEntities(f.attrs.expression || '') }));
    return out;
  }
  function parseMultiFieldFormula(c) {
    const expression = decodeXmlEntities(getTagText(c,'Expression'));
    const fields = getTags(getTagText(c,'Fields') || c, 'Field').map(f => f.attrs.field).filter(Boolean);
    return fields.map(field => ({ field, expression }));
  }
  function parseMultiRowFormula(c) {
    const field = getTagText(c,'Field');
    const expression = decodeXmlEntities(getTagText(c,'Expression'));
    if (!field && !expression) return [];
    return [{ field, expression }];
  }
  function parseFilter(c) {
    let condition = decodeXmlEntities(getTagText(c,'Expression'));
    if (!condition) {
      const m = c.match(/(?:Expression|Filter)="([^"]+)"/i);
      if (m) condition = decodeXmlEntities(m[1]);
    }
    return condition;
  }
  function parseSort(c) {
    const cols = getTags(getTagText(c,'SortInfo') || c, 'Field').map(f => ({ field: f.attrs.field || '', order: f.attrs.order || '' }));
    return cols;
  }
  function parseJoin(c) {
    const joinInfos = getTags(c, 'JoinInfo');
    const leftInfo = joinInfos.find(j => (j.attrs.connection || '').toLowerCase() === 'left');
    const rightInfo = joinInfos.find(j => (j.attrs.connection || '').toLowerCase() === 'right');
    const leftFields = leftInfo ? getTags(leftInfo.inner, 'Field').map(f => f.attrs.field || '') : [];
    const rightFields = rightInfo ? getTags(rightInfo.inner, 'Field').map(f => f.attrs.field || '') : [];
    const joinKeys = leftFields.map((left, i) => ({ left, right: rightFields[i] || '' }));
    let joinType = 'Inner';
    const explicit = c.match(/JoinType="([^"]+)"/i);
    if (explicit) joinType = explicit[1];
    return { join_type: joinType, join_keys: joinKeys };
  }
  function parseSummarize(c) {
    const fields = getTags(getTagText(c,'SummarizeFields') || c, 'SummarizeField');
    const groupBy = [], aggregations = [];
    fields.forEach(f => {
      const action = f.attrs.action || '', field = f.attrs.field || '';
      if (action.toLowerCase() === 'groupby') groupBy.push(field);
      else aggregations.push({ action, field });
    });
    return { group_by: groupBy, aggregations };
  }
  function parseInput(c) {
    const fileRaw = getTagText(c,'File');
    const { path: filePath, extra: fileExtra } = splitFilePath(fileRaw);
    const query = getTagText(c,'QueryString') || (c.match(/Query="([^"]+)"/i) || [])[1] || '';
    const connectionName = getTagText(c,'Connection') || (c.match(/Connection="([^"]+)"/i) || [])[1] || '';
    const tableAttr = (c.match(/Table="([^"]+)"/i) || [])[1] || '';
    let sourceType = 'unknown';
    if (filePath) sourceType = 'file';
    if (query || connectionName) sourceType = 'database';
    return { source_type: sourceType, file_path: filePath, table: tableAttr || fileExtra || '', query: decodeXmlEntities(query), connection_name: connectionName };
  }
  function parseOutput(c) {
    const fileRaw = getTagText(c,'File');
    const { path: filePath, extra: fileExtra } = splitFilePath(fileRaw);
    const tableAttr = (c.match(/Table="([^"]+)"/i) || [])[1] || '';
    const targetType = filePath ? 'file' : (tableAttr || fileExtra ? 'database' : 'unknown');
    return { target_type: targetType, file_path: filePath, table_name: tableAttr || fileExtra || '' };
  }

  const nodeRegex = /<Node\s+ToolID="([^"]+)"[^>]*>([\s\S]*?)<\/Node>/gi;
  let nodeMatch;
  const toolMap = new Map();
  while ((nodeMatch = nodeRegex.exec(xmlString)) !== null) {
    const toolId = nodeMatch[1];
    const nodeInner = nodeMatch[2];
    const pluginMatch = nodeInner.match(/<GuiSettings[^>]*Plugin="([^"]+)"/i);
    const plugin = pluginMatch ? pluginMatch[1] : '';
    const configMatch = nodeInner.match(/<Configuration>([\s\S]*?)<\/Configuration>/i);
    const configInner = configMatch ? configMatch[1] : '';
    const macroMatch = nodeInner.match(/<EngineSettings[^>]*Macro="([^"]*)"/i);
    const macroName = macroMatch ? macroMatch[1] : '';
    const toolTypeRaw = (plugin.split('.').pop() || 'Unknown').trim() || 'Unknown';
    if (['Browse','BrowseV2','ToolContainer','Comment','TextBox'].some(t => toolTypeRaw.includes(t))) continue;

    const lowerType = toolTypeRaw.toLowerCase();
    let toolCategory = 'transformation';
    if (plugin.includes('Input') || plugin.includes('DbFileInput') || plugin.includes('TextInput')) toolCategory = 'input';
    else if (plugin.includes('Output') || plugin.includes('DbFileOutput')) toolCategory = 'output';
    else if (lowerType.includes('filter')) toolCategory = 'filter';
    else if (lowerType === 'multirowformula') toolCategory = 'multirowformula';
    else if (lowerType === 'multifieldformula') toolCategory = 'multifieldformula';
    else if (lowerType.includes('formula')) toolCategory = 'formula';
    else if (lowerType.includes('join')) toolCategory = 'join';
    else if (lowerType.includes('union')) toolCategory = 'union';
    else if (lowerType.includes('summarize')) toolCategory = 'aggregation';
    else if (lowerType.includes('sort')) toolCategory = 'sort';
    else if (macroName) toolCategory = 'macro';

    const tool = { tool_id: toolId, plugin, tool_type: toolTypeRaw, tool_category: toolCategory, configuration_summary: {}, business_description: '' };
    if (macroName) workflow.macros.push({ tool_id: toolId, macro_name: macroName });

    if (toolCategory === 'input') {
      const parsed = parseInput(configInner);
      workflow.inputs.push(Object.assign({ tool_id: toolId }, parsed));
      tool.configuration_summary = parsed;
      tool.business_description = `Read source data from ${parsed.file_path || parsed.table || parsed.connection_name || 'unknown source'}`;
    } else if (toolCategory === 'output') {
      const parsed = parseOutput(configInner);
      workflow.outputs.push(Object.assign({ tool_id: toolId }, parsed));
      tool.configuration_summary = parsed;
      tool.business_description = `Write output data to ${parsed.file_path || parsed.table_name || 'unknown target'}`;
    } else if (toolCategory === 'filter') {
      const condition = parseFilter(configInner);
      workflow.filters.push({ tool_id: toolId, condition });
      tool.configuration_summary = { condition };
      tool.business_description = condition ? `Filter records where ${condition}` : 'Filter records (condition not detected)';
    } else if (toolCategory === 'formula' || toolCategory === 'multifieldformula' || toolCategory === 'multirowformula') {
      let fields = [];
      if (toolCategory === 'formula') fields = parseFormula(configInner);
      else if (toolCategory === 'multifieldformula') fields = parseMultiFieldFormula(configInner);
      else fields = parseMultiRowFormula(configInner);
      fields.forEach(f => workflow.formulas.push({ tool_id: toolId, field: f.field, expression: f.expression }));
      tool.configuration_summary = { fields };
      tool.business_description = fields.length === 1 ? `Calculate ${fields[0].field} using formula: ${fields[0].expression}` : (fields.length > 1 ? `Calculate fields (${fields.map(f=>f.field).join(', ')})` : 'Apply formula');
    } else if (toolCategory === 'sort') {
      const columns = parseSort(configInner);
      workflow.sorts.push({ tool_id: toolId, columns });
      tool.configuration_summary = { columns };
      tool.business_description = columns.length ? `Sort data by ${columns.map(c=>`${c.field} ${c.order}`).join(', ')}` : 'Sort data';
    } else if (toolCategory === 'join') {
      const { join_type, join_keys } = parseJoin(configInner);
      workflow.joins.push({ tool_id: toolId, join_type, join_keys });
      tool.configuration_summary = { join_type, join_keys };
      tool.business_description = join_keys.length ? `Join datasets on ${join_keys.map(k=>`${k.left}=${k.right}`).join(', ')} (${join_type})` : `Join datasets (${join_type})`;
    } else if (toolCategory === 'aggregation') {
      const { group_by, aggregations } = parseSummarize(configInner);
      workflow.aggregations.push({ tool_id: toolId, group_by, aggregations });
      tool.configuration_summary = { group_by, aggregations };
      tool.business_description = `Group by ${group_by.join(', ') || '(none)'} and aggregate: ${aggregations.map(a=>`${a.action}(${a.field})`).join(', ') || '(none)'}`;
    } else if (toolCategory === 'union') {
      tool.business_description = 'Union multiple datasets';
    } else if (toolCategory === 'macro') {
      tool.business_description = `Run macro: ${macroName}`;
    } else {
      tool.business_description = `Process data with ${toolTypeRaw}`;
    }
    workflow.tools.push(tool);
    toolMap.set(toolId, tool);
  }
  workflow.tool_count = workflow.tools.length;

  const connRegex = /<Connection>[\s\S]*?<Origin\s+ToolID="([^"]+)"[^>]*\/?>[\s\S]*?<Destination\s+ToolID="([^"]+)"[^>]*\/?>[\s\S]*?<\/Connection>/gi;
  let connMatch;
  const graph = {};
  while ((connMatch = connRegex.exec(xmlString)) !== null) {
    const from = connMatch[1], to = connMatch[2];
    workflow.connections.push({ from_tool: from, to_tool: to });
    if (!graph[from]) graph[from] = [];
    graph[from].push(to);
  }
  workflow.dependency_graph = graph;

  const visited = new Set();
  const flow = [], steps = [];
  function traverse(toolId, stepNum) {
    if (visited.has(toolId)) return;
    visited.add(toolId);
    const tool = toolMap.get(toolId);
    if (tool) { flow.push(tool.tool_type); steps.push({ step: stepNum, tool_id: toolId, tool_type: tool.tool_type }); }
    (graph[toolId] || []).forEach(nextId => traverse(nextId, stepNum + 1));
  }
  workflow.inputs.forEach((inp, idx) => traverse(inp.tool_id, idx + 1));
  workflow.tools.forEach((t, idx) => traverse(t.tool_id, workflow.inputs.length + idx + 1));
  workflow.execution_flow = flow;
  workflow.execution_steps = steps;
  workflow.business_logic_candidates = steps.map(s => {
    const tool = toolMap.get(s.tool_id);
    return (tool && tool.business_description) ? `${tool.business_description} (${s.tool_type})` : `Process data with ${s.tool_type}`;
  });

  return workflow;
}

function parseADFJson(rawContent, project_name, filename) {
  const root = JSON.parse(rawContent);

  // ARM deployment templates often name resources via "[concat(parameters('factoryName'), '/PipelineName')]"
  // instead of a literal string. Pull the trailing literal path segment out of that expression when present.
  function cleanArmName(raw, fallback) {
    if (!raw || typeof raw !== 'string') return fallback;
    const concatMatch = raw.match(/\/([\w-]+)'\)\s*\]?\s*$/);
    if (concatMatch) return concatMatch[1];
    if (/^\s*\[/.test(raw)) return fallback;
    return raw.split('/').pop();
  }

  function unwrapResource(root) {
    if (root.properties && Array.isArray(root.properties.activities)) {
      return { kind: 'pipeline', name: root.name || 'UnnamedPipeline', properties: root.properties };
    }
    if (root.properties && (root.properties.type === 'MappingDataFlow' ||
        (root.properties.typeProperties && Array.isArray(root.properties.typeProperties.transformations)))) {
      return { kind: 'dataflow', name: root.name || 'UnnamedDataFlow', properties: root.properties };
    }
    if (Array.isArray(root.resources)) {
      const pipelineRes = root.resources.find(r => typeof r.type === 'string' && r.type.toLowerCase().includes('/pipelines'));
      if (pipelineRes) return { kind: 'pipeline', name: cleanArmName(pipelineRes.name, 'UnnamedPipeline'), properties: pipelineRes.properties };
      const dataflowRes = root.resources.find(r => typeof r.type === 'string' && r.type.toLowerCase().includes('/dataflows'));
      if (dataflowRes) return { kind: 'dataflow', name: cleanArmName(dataflowRes.name, 'UnnamedDataFlow'), properties: dataflowRes.properties };
    }
    throw new Error('Unrecognized ADF JSON: expected a pipeline export (properties.activities) or a mapping data flow export (properties.typeProperties.transformations)');
  }

  const resource = unwrapResource(root);

  // ARM deployment templates commonly parameterize activity config via "[parameters('X')]" / "[variables('X')]" /
  // "[concat(...)]" expressions that have no real value until the template is deployed. Collect every such
  // placeholder found anywhere in this resource so the Generator/Repair agents can be told explicitly not to
  // treat them as literal data (see the ARM-template rule in the Generator/Repair system prompts).
  const armPlaceholders = new Set();
  function collectArmPlaceholders(value) {
    if (typeof value === 'string') {
      if (/^\s*\[(parameters|variables|concat|resourceId|deployment|pipeline)\(/i.test(value)) armPlaceholders.add(value);
    } else if (Array.isArray(value)) {
      value.forEach(collectArmPlaceholders);
    } else if (value && typeof value === 'object') {
      Object.values(value).forEach(collectArmPlaceholders);
    }
  }
  collectArmPlaceholders(resource.properties);

  const workflow = {
    project_name, filename,
    workflow_name: resource.name,
    tool_count: 0, tools: [], connections: [], inputs: [], outputs: [],
    filters: [], formulas: [], sorts: [], joins: [], unions: [], aggregations: [],
    macros: [], execution_flow: [], execution_steps: [], dependency_graph: {},
    business_logic_candidates: []
  };

  const toolMap = new Map();

  function refName(ref) {
    if (!ref) return '';
    return ref.referenceName || ref.name || '';
  }

  if (resource.kind === 'pipeline') {
    const activities = resource.properties.activities || [];

    // Container activities (ForEach/Until/IfCondition/Switch) hold their real work in a NESTED activities
    // array/object rather than the top-level activities list. Recurse into them so e.g. a Copy activity buried
    // inside a ForEach loop becomes its own first-class tool_id instead of invisible JSON inside the loop's
    // configuration_summary (which is exactly what a plain single-level scan would miss).
    function processActivity(act, containerId) {
      const toolId = act.name;
      const type = act.type || 'Unknown';
      const lowerType = type.toLowerCase();
      let toolCategory = 'transformation';
      let businessDescription = `Execute ${type} activity`;
      const tp = act.typeProperties || {};

      if (lowerType === 'copy') {
        toolCategory = 'input';
        const sourceType = (tp.source && typeof tp.source === 'object' && tp.source.type) || 'unknown';
        const inputNames = (act.inputs || []).map(refName).join(', ');
        const outputNames = (act.outputs || []).map(refName).join(', ');
        workflow.inputs.push({ tool_id: toolId, source_type: 'dataset', file_path: '', table: inputNames, query: '', connection_name: sourceType });
        workflow.outputs.push({ tool_id: toolId, target_type: 'dataset', file_path: '', table_name: outputNames });
        businessDescription = `Copy data from ${inputNames || 'source dataset'} to ${outputNames || 'sink dataset'}`;
      } else if (lowerType === 'lookup') {
        toolCategory = 'input';
        const ds = tp.dataset;
        const inputNames = ds ? refName(ds) : '';
        workflow.inputs.push({ tool_id: toolId, source_type: 'lookup', file_path: '', table: inputNames,
          query: (tp.source && typeof tp.source === 'object' && tp.source.query) || '', connection_name: '' });
        businessDescription = `Lookup reference data from ${inputNames || 'dataset'}`;
      } else if (lowerType === 'filter') {
        toolCategory = 'filter';
        const condition = (tp.condition && tp.condition.value) || '';
        workflow.filters.push({ tool_id: toolId, condition });
        businessDescription = condition ? `Filter records where ${condition}` : 'Filter records (condition not detected)';
      } else if (lowerType === 'executedataflow') {
        toolCategory = 'macro';
        const dfRef = tp.dataFlow;
        const dfName = dfRef ? refName(dfRef) : '';
        workflow.macros.push({ tool_id: toolId, macro_name: dfName });
        businessDescription = `Execute mapping data flow: ${dfName}`;
      } else if (lowerType === 'sort') {
        toolCategory = 'sort';
        businessDescription = 'Sort data';
      } else if (lowerType === 'setvariable' || lowerType === 'appendvariable') {
        toolCategory = 'transformation';
        businessDescription = `Set pipeline variable ${tp.variableName || ''}`;
      } else if (lowerType === 'foreach') {
        toolCategory = 'transformation';
        const itemsExpr = (tp.items && tp.items.value) || '';
        businessDescription = `Loop over items from: ${itemsExpr || '(unknown items expression)'}${tp.batchCount ? ` (batch size ${tp.batchCount})` : ''} — execute the nested activities once per item`;
      } else if (lowerType === 'until') {
        toolCategory = 'transformation';
        const expr = (tp.expression && tp.expression.value) || '';
        businessDescription = `Repeat nested activities until: ${expr || '(unknown condition)'}`;
      } else if (lowerType === 'ifcondition') {
        toolCategory = 'transformation';
        const expr = (tp.expression && tp.expression.value) || '';
        businessDescription = `Branch on condition: ${expr || '(unknown condition)'} — different nested activities run for true/false`;
      } else if (lowerType === 'switch') {
        toolCategory = 'transformation';
        const expr = (tp.on && tp.on.value) || '';
        businessDescription = `Switch on: ${expr || '(unknown expression)'} — different nested activities run per case`;
      } else {
        businessDescription = `Execute ${type} activity`;
      }

      // Exclude nested-activity arrays from configuration_summary: they're extracted as their own tools below,
      // and leaving the raw nested JSON in here just re-leaks it (with any ARM placeholders) into the LLM prompt.
      const configSummary = Object.assign({}, tp);
      delete configSummary.activities;
      delete configSummary.ifTrueActivities;
      delete configSummary.ifFalseActivities;
      delete configSummary.cases;
      delete configSummary.defaultActivities;

      const tool = { tool_id: toolId, plugin: `ADF.${type}`, tool_type: type, tool_category: toolCategory,
        configuration_summary: configSummary, business_description: businessDescription };
      workflow.tools.push(tool);
      toolMap.set(toolId, tool);

      if (containerId) workflow.connections.push({ from_tool: containerId, to_tool: toolId });
      (act.dependsOn || []).forEach(dep => {
        workflow.connections.push({ from_tool: dep.activity, to_tool: toolId });
      });

      const nestedGroups = [];
      if (lowerType === 'foreach' || lowerType === 'until') {
        if (Array.isArray(tp.activities)) nestedGroups.push(tp.activities);
      } else if (lowerType === 'ifcondition') {
        if (Array.isArray(tp.ifTrueActivities)) nestedGroups.push(tp.ifTrueActivities);
        if (Array.isArray(tp.ifFalseActivities)) nestedGroups.push(tp.ifFalseActivities);
      } else if (lowerType === 'switch') {
        (tp.cases || []).forEach(c => { if (Array.isArray(c.activities)) nestedGroups.push(c.activities); });
        if (Array.isArray(tp.defaultActivities)) nestedGroups.push(tp.defaultActivities);
      }
      nestedGroups.forEach(group => group.forEach(nestedAct => processActivity(nestedAct, toolId)));
    }

    activities.forEach(act => processActivity(act, null));
  } else {
    const tp = resource.properties.typeProperties || {};
    const declaredTransforms = tp.transformations || [];
    const script = tp.script || '';

    declaredTransforms.forEach(t => {
      toolMap.set(t.name, { tool_id: t.name, plugin: 'ADF.DataFlowTransformation', tool_type: 'Unknown',
        tool_category: 'transformation', configuration_summary: {}, business_description: `Process data with ${t.name}` });
    });
    (tp.sources || []).forEach(s => {
      if (!toolMap.has(s.name)) toolMap.set(s.name, { tool_id: s.name, plugin: 'ADF.Source', tool_type: 'Source',
        tool_category: 'input', configuration_summary: {}, business_description: `Read source data from ${s.name}` });
    });
    (tp.sinks || []).forEach(s => {
      if (!toolMap.has(s.name)) toolMap.set(s.name, { tool_id: s.name, plugin: 'ADF.Sink', tool_type: 'Sink',
        tool_category: 'output', configuration_summary: {}, business_description: `Write output data to ${s.name}` });
    });

    function extractBalanced(str, startIdx) {
      let depth = 0, i = startIdx;
      for (; i < str.length; i++) {
        if (str[i] === '(') depth++;
        else if (str[i] === ')') { depth--; if (depth === 0) return str.substring(startIdx + 1, i); }
      }
      return str.substring(startIdx + 1);
    }

    const statements = script.split(/\r?\n(?=\s*[\w,\s]+?\w+\s*\()/).map(s => s.trim()).filter(Boolean);
    statements.forEach(stmt => {
      const arrowIdx = stmt.lastIndexOf('~>');
      if (arrowIdx === -1) return;
      const outputName = stmt.substring(arrowIdx + 2).trim().split(/\s+/)[0];
      const head = stmt.substring(0, arrowIdx).trim();
      const parenIdx = head.indexOf('(');
      if (parenIdx === -1) return;
      const beforeParen = head.substring(0, parenIdx).trim();
      const tokens = beforeParen.split(/\s+/).filter(Boolean);
      const transformType = (tokens.pop() || '').toLowerCase();
      const inputNames = tokens.join(' ').split(',').map(s => s.trim()).filter(Boolean);
      const args = extractBalanced(head, parenIdx);

      inputNames.forEach(inputName => {
        workflow.connections.push({ from_tool: inputName, to_tool: outputName });
      });

      let tool = toolMap.get(outputName);
      if (!tool) {
        tool = { tool_id: outputName, plugin: `ADF.${transformType}`, tool_type: transformType,
          tool_category: 'transformation', configuration_summary: {}, business_description: `Process data with ${transformType}` };
        toolMap.set(outputName, tool);
      }
      tool.plugin = `ADF.${transformType}`;
      tool.tool_type = transformType;
      tool.configuration_summary = { raw_args: args };

      if (transformType === 'source') {
        tool.tool_category = 'input';
        workflow.inputs.push({ tool_id: outputName, source_type: 'dataflow_source', file_path: '', table: '', query: '', connection_name: '' });
        tool.business_description = `Read source data (${outputName})`;
      } else if (transformType === 'sink') {
        tool.tool_category = 'output';
        workflow.outputs.push({ tool_id: outputName, target_type: 'dataflow_sink', file_path: '', table_name: '' });
        tool.business_description = `Write output data (${outputName})`;
      } else if (transformType === 'filter') {
        tool.tool_category = 'filter';
        const condition = args.split(',')[0] ? args.split(',')[0].trim() : args.trim();
        workflow.filters.push({ tool_id: outputName, condition });
        tool.business_description = condition ? `Filter records where ${condition}` : 'Filter records';
      } else if (transformType === 'derive' || transformType === 'select' || transformType === 'cast') {
        tool.tool_category = 'formula';
        const mapMatches = args.match(/mapColumn\(([^)]*)\)/g) || [];
        const fields = mapMatches.map(m => {
          const inner = m.replace(/^mapColumn\(/, '').replace(/\)$/, '');
          const parts = inner.split('=');
          return { field: (parts[0] || '').trim(), expression: (parts[1] || parts[0] || '').trim() };
        });
        fields.forEach(f => workflow.formulas.push({ tool_id: outputName, field: f.field, expression: f.expression }));
        tool.business_description = fields.length ? `Calculate fields (${fields.map(f => f.field).join(', ')})` : `Derive/select columns (${outputName})`;
      } else if (transformType === 'join' || transformType === 'lookup' || transformType === 'exists') {
        tool.tool_category = 'join';
        const typeMatch = args.match(/joinType\s*:\s*'([^']+)'/i);
        const onMatch = args.match(/\(([^()]*==[^()]*)\)/);
        const joinKeys = [];
        if (onMatch) {
          const eq = onMatch[1].split('==').map(s => s.trim());
          joinKeys.push({ left: eq[0] || '', right: eq[1] || '' });
        }
        workflow.joins.push({ tool_id: outputName, join_type: typeMatch ? typeMatch[1] : (transformType === 'lookup' ? 'Left' : 'Inner'), join_keys: joinKeys });
        tool.business_description = joinKeys.length ? `Join datasets on ${joinKeys.map(k => `${k.left}=${k.right}`).join(', ')}` : `Join datasets (${transformType})`;
      } else if (transformType === 'aggregate') {
        tool.tool_category = 'aggregation';
        const groupMatch = args.match(/groupBy\(([^)]*)\)/);
        const groupBy = groupMatch ? groupMatch[1].split(',').map(s => s.trim()).filter(Boolean) : [];
        const aggMatches = args.match(/mapColumn\(([^)]*)\)/g) || [];
        const aggregations = aggMatches.map(m => {
          const inner = m.replace(/^mapColumn\(/, '').replace(/\)$/, '');
          const parts = inner.split('=');
          return { action: (parts[1] || '').trim(), field: (parts[0] || '').trim() };
        });
        workflow.aggregations.push({ tool_id: outputName, group_by: groupBy, aggregations });
        tool.business_description = `Group by ${groupBy.join(', ') || '(none)'} and aggregate: ${aggregations.map(a => `${a.action}(${a.field})`).join(', ') || '(none)'}`;
      } else if (transformType === 'sort') {
        tool.tool_category = 'sort';
        const cols = args.split(',').map(s => s.trim()).filter(Boolean).map(c => {
          const m = c.match(/^(.*?)\s+(asc|desc)$/i);
          return m ? { field: m[1].trim(), order: m[2] } : { field: c, order: '' };
        });
        workflow.sorts.push({ tool_id: outputName, columns: cols });
        tool.business_description = cols.length ? `Sort data by ${cols.map(c => `${c.field} ${c.order}`).join(', ')}` : 'Sort data';
      } else if (transformType === 'union') {
        tool.tool_category = 'union';
        tool.business_description = 'Union multiple datasets';
      } else {
        tool.tool_category = 'transformation';
        tool.business_description = `Process data with ${transformType} (${outputName})`;
      }
    });
  }

  workflow.tools = Array.from(toolMap.values());
  workflow.tool_count = workflow.tools.length;

  const graph = {};
  workflow.connections.forEach(c => {
    if (!graph[c.from_tool]) graph[c.from_tool] = [];
    graph[c.from_tool].push(c.to_tool);
  });
  workflow.dependency_graph = graph;

  const visited = new Set();
  const flow = [], steps = [];
  function traverse(toolId, stepNum) {
    if (visited.has(toolId) || !toolId) return;
    visited.add(toolId);
    const tool = toolMap.get(toolId);
    if (tool) { flow.push(tool.tool_type); steps.push({ step: stepNum, tool_id: toolId, tool_type: tool.tool_type }); }
    (graph[toolId] || []).forEach(nextId => traverse(nextId, stepNum + 1));
  }
  const roots = workflow.tools.filter(t => t.tool_category === 'input').map(t => t.tool_id);
  roots.forEach((id, idx) => traverse(id, idx + 1));
  workflow.tools.forEach((t, idx) => traverse(t.tool_id, roots.length + idx + 1));
  workflow.execution_flow = flow;
  workflow.execution_steps = steps;
  workflow.business_logic_candidates = steps.map(s => {
    const tool = toolMap.get(s.tool_id);
    return (tool && tool.business_description) ? `${tool.business_description} (${s.tool_type})` : `Process data with ${s.tool_type}`;
  });

  workflow.is_arm_template_deployment = armPlaceholders.size > 0;
  workflow.unresolved_arm_parameters = Array.from(armPlaceholders);

  return workflow;
}

