function stripJsonComments(text) {
  // Removes // line comments and /* */ block comments while respecting strings
  let result = '';
  let inString = false;
  let stringChar = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inString) {
      result += ch;
      if (ch === '\\') { result += next; i++; continue; }
      if (ch === stringChar) inString = false;
      continue;
    }
    if (ch === '"' || ch === "'") {
      inString = true;
      stringChar = ch;
      result += ch;
      continue;
    }
    if (ch === '/' && next === '/') {
      while (i < text.length && text[i] !== '\n') i++;
      continue;
    }
    if (ch === '/' && next === '*') {
      i += 2;
      while (i < text.length && !(text[i] === '*' && text[i + 1] === '/')) i++;
      i++;
      continue;
    }
    result += ch;
  }
  return result;
}

// NEW: fixes missing commas between list/object items (e.g. "a"\n"b" -> "a",\n"b")
function insertMissingCommas(text) {
  // Step 1: pull all quoted strings out into placeholders so we don't touch their contents
  const strings = [];
  let skeleton = '';
  let inString = false, escape = false, current = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      current += ch;
      if (escape) { escape = false; }
      else if (ch === '\\') { escape = true; }
      else if (ch === '"') {
        inString = false;
        strings.push(current);
        skeleton += `\u0001${strings.length - 1}\u0002`;
        current = '';
      }
      continue;
    }
    if (ch === '"') { inString = true; current = '"'; continue; }
    skeleton += ch;
  }

  // Step 2: insert a comma wherever one value ends and another begins with nothing but
  // whitespace between them (the classic "AI forgot a comma" pattern)
  skeleton = skeleton.replace(/([}\]\u0002])(\s*)([{\[\u0001])/g, '$1,$2$3');
  skeleton = skeleton.replace(/([0-9a-zA-Z])(\s+)([{\[\u0001])/g, '$1,$2$3');

  // Step 3: put the real string contents back
  return skeleton.replace(/\u0001(\d+)\u0002/g, (m, idx) => strings[Number(idx)]);
}

function extractJsonObject(raw) {
  if (!raw) throw new Error('Empty response');
  let text = raw.trim();
  const fenceMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenceMatch) text = fenceMatch[1].trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('No JSON object found in response');
  text = text.substring(start, end + 1);
  text = stripJsonComments(text);
  text = text.replace(/,(\s*[\]}])/g, '$1');
  text = insertMissingCommas(text);

  console.log('CONTEXT:', JSON.stringify(text.slice(3450, 3650))); // TEMP DEBUG

  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error(`Could not parse JSON even after repair: ${err.message}`);
  }
}

