    repair_cycle: $json.repair_cycle || 0,
    fidelity_coverage_pct: $json.fidelity_coverage_pct ?? null,
    poll_attempt: 0
  }
};

// Upload HTTP node replaces $json with the (empty) import response.
// Restore the real state so it survives into Run Job.
const prior = $('Base64 Encode').item.json;
return [{ json: { ...prior } }];

// Run Job response is { run_id: ... } and replaces $json — merge back in.
const prior = $('Carry State After Upload1').item.json;
return [{ json: { ...prior, run_id: $json.run_id, poll_attempt: 0 } }];

// Get Run Status response replaces $json — merge prior loop state back in,
// then let the response's own fields (run_id, state, tasks, job_id) sit on top.
const prior = $('Increment Attempt[COUNTER]').item.json;
return [{ json: { ...prior, ...$json } }];

const resp = $json.notebook_output_response || {};
if (!resp.notebook_output || !resp.notebook_output.result) {
  // No exit payload at all (e.g. the notebook crashed before reaching dbutils.notebook.exit,
  // or Databricks returned no output). Shape this as a real actual_result so every downstream
  // consumer (SUCCESS?1, Build Error Context1) sees a consistent, non-null error_message/error_type
  // instead of silently nulling out the error_history columns.
  return [{
    json: {
      ...$json,
      actual_result: {
        status: 'FAILED',
        error_type: 'NoNotebookOutput',
        error_message: (resp.notebook_output && resp.notebook_output.diagnostics) || (resp.error) || 'No notebook output returned (notebook likely raised before reaching dbutils.notebook.exit)',
        failed_operation: null
      },
      metadata: resp
    }
  }];
}
const payload = JSON.parse(resp.notebook_output.result);
if (payload.error_type === 'NotebookExit' && payload.error_message) {
  return [{ json: { ...$json, actual_result: JSON.parse(payload.error_message), metadata: resp } }];
}
return [{ json: { ...$json, actual_result: payload, metadata: resp } }];

const state = $json.metadata && $json.metadata.state || {};
return [{
  json: {
    run_id: $json.run_id || ($json.metadata && $json.metadata.run_id) || null,
    repair_cycle: $json.repair_cycle || 0,
