    failure_pattern: 'New Failure',
    generated_code: $json.cleaned_code || '',
    repair_reason: 'runtime_error',
    summary: null
  }
}];

function extractJsonObject(raw) {
  if (!raw) throw new Error('Empty response');
  let text = raw.trim();
  const fenceMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenceMatch) text = fenceMatch[1].trim();
  const start = text.indexOf('{');
  if (start === -1) throw new Error('No JSON object found in response');
  let depth = 0, inString = false, escape = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escape) { escape = false; }
      else if (ch === String.fromCharCode(92)) { escape = true; }
      else if (ch === '"') { inString = false; }
      continue;
    }
    if (ch === '"') { inString = true; continue; }
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) return text.substring(start, i + 1); }
  }
  throw new Error('Unbalanced JSON object in response (no matching closing brace found)');
}

let jsonText;
try { jsonText = extractJsonObject($json.output || ''); } catch (e) { throw new Error('Error Classifier1 returned no valid JSON object: ' + e.message); }
const summary = JSON.parse(jsonText);

const source = $('Build Error Context').item.json;

function hashCode(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (Math.imul(31, h) + str.charCodeAt(i)) | 0; }
  return (h >>> 0).toString(16);
}
const normalizedCode = (source.generated_code || '').replace(/\s+/g, ' ').trim();

return [{
  json: {
    run_id: source.run_id,
    repair_cycle: source.repair_cycle,
    status: source.status,
    error_message: source.error_message,
    error_type: source.error_type,
    error_category: summary.error_category || source.error_type || 'Unknown',
    is_file_path_error: summary.is_file_path_error === true,
    failure_pattern: summary.failure_pattern || source.failure_pattern,
    generated_code: source.generated_code,
    code_hash: hashCode(normalizedCode),
    summary: summary.summary || null,
    root_cause: summary.root_cause || null,
    suggested_resolution: summary.suggested_resolution || null,
    repair_reason: 'runtime_error',
    fixed: false,
    created_at: new Date().toISOString()
  }
}];

const sessionId = $execution.id;
const history = items
  .filter(item => item.json.session_id === sessionId)
  .map(item => ({
    error_message: item.json.error_message,
    error_type: item.json.error_type,
    error_category: item.json.error_category,
    failure_pattern: item.json.failure_pattern,
    summary: item.json.summary,
    generated_code: item.json.generated_code,
    code_hash: item.json.code_hash
  }));
const current = $('Merge Classifier Output').item.json;
return [{ json: { ...current, error_memory: history } }];

const mc = $json; // already merged: repair_cycle, is_file_path_error, failure_pattern, code_hash, error_memory
const memory = mc.error_memory || [];

const REPEAT_THRESHOLD = 5;      // raised from 3 - a single similar-looking repair shouldn't trip an early stop
const SAME_CODE_REPEAT_THRESHOLD = 2;
const MIN_CYCLES_BEFORE_STOP = 2; // always allow at least 2 full generate -> static -> repair cycles
const MAX_REPAIR_CYCLES = 8;

const repairCycle = mc.repair_cycle || 0;
const isRealFilePathError = mc.is_file_path_error === true; // only ever set true after a real Databricks run (see Merge Classifier Output1)
const sameFailureCount = memory.filter(m => m.failure_pattern === mc.failure_pattern).length;
const sameFailureSameCodeCount = memory.filter(m => m.failure_pattern === mc.failure_pattern && m.code_hash === mc.code_hash).length;
const patternExhausted = sameFailureCount >= REPEAT_THRESHOLD || sameFailureSameCodeCount >= SAME_CODE_REPEAT_THRESHOLD;
const maxCyclesReached = repairCycle >= MAX_REPAIR_CYCLES;
const belowMinCycles = repairCycle < MIN_CYCLES_BEFORE_STOP;

let shouldRetry = true;
let stopReason = null;

if (maxCyclesReached) {
  shouldRetry = false; stopReason = 'max_repair_cycles_reached';
} else if (belowMinCycles) {
  shouldRetry = true; stopReason = null;
} else if (isRealFilePathError) {
  shouldRetry = false; stopReason = 'file_path_error';
} else if (patternExhausted) {
  shouldRetry = false; stopReason = 'failure_pattern_repeated';
}

return [{ json: { ...mc, should_retry: shouldRetry, stop_reason: stopReason } }];

const repairCycle = ($json.repair_cycle || 0) + 1;

let ir;
try { ir = $('Parse Enriched IR1').first().json; } catch (e) { ir = $('Parser - Canonical IR1').first().json; }
let blueprint = null;
try { blueprint = $('Parse Migration Blueprint1').first().json.migration_blueprint; } catch (e) { blueprint = null; }

return [{
  json: {
    repair_cycle: repairCycle,
    repair_reason: $json.repair_reason || 'runtime_error',
    ir_context: JSON.stringify(ir),
    blueprint_context: blueprint ? JSON.stringify(blueprint) : '',
    generated_code: $json.generated_code || $json.cleaned_code || '',
    run_status: $json.status || null,
    error_type: $json.error_type || null,
    error_category: $json.error_category || null,
    error: $json.error_message || null,
    error_trace: $json.error_trace || null,
    root_cause: $json.root_cause || null,
    suggested_resolution: $json.suggested_resolution || null,
