let code = $json.output || '';
code = code.replace(/```python\s*/gi, '').replace(/```/g, '').trim();
if (!code) throw new Error('Repair agent returned empty code');
const ctx = $('Build Repair Context').item.json;
return [{ json: { cleaned_code: code, repair_cycle: ctx.repair_cycle, repair_reason: ctx.repair_reason, error_memory: ctx.error_memory } }];

function hashCode(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (Math.imul(31, h) + str.charCodeAt(i)) | 0; }
  return (h >>> 0).toString(16);
}
function similarity(a, b) {
  const la = a.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const lb = b.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  if (la.length === 0 || lb.length === 0) return 0;
  const setB = new Set(lb);
  const shared = la.filter(l => setB.has(l)).length;
  return shared / Math.max(la.length, lb.length);
}

const newCode = $json.cleaned_code || '';
const repairCycle = $json.repair_cycle || 1;
const newHash = hashCode(newCode.replace(/\s+/g, ' ').trim());
const memory = $json.error_memory || [];

let isNovel = true;
if (repairCycle >= 2) {
  isNovel = !memory.some(m => m.code_hash === newHash || similarity(newCode, m.generated_code || '') >= 0.9);
}

return [{ json: { cleaned_code: newCode, code_hash: newHash, is_novel: isNovel, repair_cycle: repairCycle, repair_reason: $json.repair_reason } }];

let payload;

if ($json.actual_result) {
